/// Execute a replacement on the given subject by replacing all matches
/// with this printer's replacement string. To access the result of the
/// replacement, use the `replacer.replacement()` method.
///
/// Contextual lines are only rewritten when the searcher inverted matches,
/// since those lines correspond to original matches. This can fail if the
/// underlying matcher reports an error.
fn replace_all<M: Matcher>(
    &self,
    replacer: &mut Replacer<M>,
    searcher: &Searcher,
    matcher: &M,

display.text:
